def compute(vars):
    total_cost = vars["v1"]
    principal_amount = vars["v2"]
    prepayment_penalty = vars["v3"]
    interest_expense = total_cost - principal_amount - prepayment_penalty

    return {
        "value": interest_expense,
        "trace": {
            "total_cost": total_cost,
            "principal_amount": principal_amount,
            "prepayment_penalty": prepayment_penalty,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "interest expense"
            }
        }
    }
